"""Inventory completed compact-page experiments; importing performs no archive/hash/JVM work."""

import importlib.util
import json
import os
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
PHASE = 'result-coordinate-evidence/compact-page-followup'
MANIFEST = PHASE + '/delivery/runtime-bundle-manifest.json'
sys.path.insert(0, str(ROOT / 'result-coordinate-evidence/materializer-followup'))
from comparison_runtime_io import (Inventory, file_hash, json_bytes, member_relative, path_under, portable,
                                   publish_no_replace, real_tree, recorded_relative, require, sha_bytes,
                                   signature, tree_digest)


def import_path(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    sys.path.insert(0, str(path.parent))
    try:
        spec.loader.exec_module(module)
    finally:
        sys.path.remove(str(path.parent))
    return module


def source_argument(argv, schema):
    if schema == 'query-harness':
        values = [argument.removeprefix('--source=') for argument in argv if argument.startswith('--source=')]
        require(len(values) == 1, 'Expected exactly one query source identity')
        return values[0]
    require(schema == 'retry-probe', 'Unknown command schema')
    at = argv.index('-cp')
    require(len(argv) == at + 5 and argv[at + 2]
            == 'org.eclipse.rdf4j.sail.lmdb.evaluation.CompactPageRetryProbe', 'Unexpected retry argument schema')
    return argv[at + 4]


def catalog(repo, inventory):
    identity = import_path('compact_delivery_identity', repo / PHASE / 'runtime_identity.py')
    comparison = import_path('compact_delivery_comparison', repo / PHASE / 'run-comparison.py')
    original_cp, original_manifest = identity.original_identity()
    protocol, primary = comparison.validate_protocol(repo / PHASE / 'protocol.json')
    completed = inventory.json(PHASE + '/comparison-v1/summary.json')
    require(completed['complete'] and completed['completedJvms'] == 36 and not completed['errors']
            and completed['rawQueryCount'] == 468 and completed['rawMeasuredQueryCount'] == 180,
            'This completed-comparison package requires all 36 fixed forks and their 468 queries')
    preservation = inventory.json(PHASE + '/comparison-v1/post-run-preservation.json')
    require(preservation['identityFilesUnchanged'] and all(preservation['runtimeIdentitiesUnchanged'].values()),
            'Comparison source/runtime preservation failed')
    artifacts, runtimes = {}, {}

    def register(name, classpath, manifest, source_identity, descriptor=None):
        require(classpath == os.pathsep.join(entry['path'] for entry in manifest), 'Classpath order differs: ' + name)
        entries = []
        for entry in manifest:
            relative = recorded_relative(entry['path'], str(repo))
            if relative not in artifacts:
                if entry['kind'] == 'tree':
                    files = inventory.tree(relative)
                    require(len(files) == entry['files'] and tree_digest(files) == entry['sha256'],
                            'Changed artifact: ' + relative)
                else:
                    require(entry['kind'] == 'file' and relative.endswith('.jar'), 'Unexpected artifact type')
                    inventory.add(relative, entry['sha256'])
                artifacts[relative] = entry | {'path': 'rdf4j/' + relative, 'originalAbsolutePath': entry['path']}
            existing = artifacts[relative]
            require(existing['sha256'] == entry['sha256'] and existing['kind'] == entry['kind'],
                    'Conflicting artifact identity')
            entries.append(existing['path'])
        runtimes[name] = {'originalClasspath': classpath, 'originalManifest': manifest, 'entries': entries,
                          'sourceIdentity': source_identity, 'descriptor': descriptor}

    def descriptor_runtime(name, relative):
        descriptor = inventory.json(relative)
        inputs = comparison.descriptor_inputs(descriptor)
        for path in inputs.values():
            inventory.add(recorded_relative(str(path), str(repo)))
        cp = inventory.read(recorded_relative(descriptor['classpathFile'], str(repo))).decode().strip()
        manifest = inventory.json(recorded_relative(descriptor['classpathManifestFile'], str(repo)))
        register(name, cp, manifest, descriptor['sourceIdentity'], descriptor)
        runtimes[name]['descriptorPath'] = 'rdf4j/' + relative
        return manifest

    register('original-base', original_cp, original_manifest, identity.ORIGINAL_SOURCE)
    original = descriptor_runtime('timing-original', PHASE + '/compiled-v1/runtime-descriptor.json')
    candidate_base = descriptor_runtime('candidate-base', PHASE + '/runtimes/compact-page/runtime-descriptor.json')
    candidate = descriptor_runtime('timing-compact', PHASE + '/candidate-runtime/runtime-descriptor.json')
    require(original == primary['original']['manifest'] and original[1:] == original_manifest,
            'Original/common composition differs from timed protocol')
    require(candidate == primary['candidate']['manifest'] and candidate == [original[0]] + candidate_base,
            'Candidate/common composition differs from timed protocol')
    require(len(candidate_base) == 127 and all(candidate_base[i] == original_manifest[i] for i in range(127) if i != 1),
            'Candidate changed another frozen base entry')

    diagnostic = import_path('compact_delivery_diagnostic', repo / PHASE / 'diagnostic/run_diagnostic.py')
    diagnostic_plan = diagnostic.read_plan()
    diagnostic_analysis = inventory.json(PHASE + '/diagnostic/analysis.json')
    require(diagnostic_analysis['validDiagnostic'], 'Representation diagnostic did not qualify')
    raw_outputs = {}
    for variant in ('original', 'compact'):
        runtime = diagnostic.read_runtime(diagnostic_plan, variant)
        register('page-' + variant, runtime['classpath'], runtime['manifest'], runtime['sourceIdentity'], runtime)
        require(runtime['manifest'][1:] == (original if variant == 'original' else candidate),
                'Diagnostic changed its selected common/base runtime')
        relative = PHASE + '/diagnostic/generated/' + variant + '/compiled-output'
        raw = inventory.tree(relative)
        require(raw == runtime['compiledClasses'], 'Raw diagnostic javac output differs')
        raw_outputs[variant] = {'path': 'rdf4j/' + relative, 'files': raw}

    retry = import_path('compact_delivery_retry', repo / PHASE / 'diagnostic/retry-probe/run_retry_probe.py')
    retry_plan = retry.read_plan()
    retry_runtime = inventory.json(PHASE + '/diagnostic/retry-probe/runtime.json')
    require(retry_runtime['protocolSha256'] == file_hash(repo / PHASE / 'diagnostic/retry-probe/prospective-protocol.json')
            and retry_runtime['sourceIdentity'] == retry_plan['sourceIdentity'], 'Retry source/protocol differs')
    register('retry-probe', retry_runtime['classpath'], retry_runtime['manifest'], retry_runtime['sourceIdentity'], retry_runtime)
    require(retry_runtime['manifest'][1:] == runtimes['page-compact']['originalManifest'],
            'Retry probe changed compact diagnostic artifacts')
    require(inventory.json(PHASE + '/diagnostic/retry-probe/analysis.json')['valid'], 'Retry probe did not qualify')
    require(len(runtimes) == 7 and len(artifacts) == 132, 'Unexpected runtime/unique-artifact count')

    command_files = []
    for round_index, order in enumerate(protocol['balancedOrders']):
        for fixture_position, fixture in enumerate(protocol['fixtureOrdersByRound'][round_index]):
            for position, arm in enumerate(order):
                folder = f'round-{round_index:02d}-{fixture_position:02d}-{fixture}-{position:02d}-{arm}'
                command_files.append(('primary', 'query-harness', PHASE + '/comparison-v1/' + folder + '/command.json'))
    command_files += [('page-diagnostic', 'query-harness', PHASE + '/diagnostic/runs/' + variant + '/command.json')
                      for variant in ('original', 'compact')]
    command_files.append(('retry-probe', 'retry-probe', PHASE + '/diagnostic/retry-probe/run/command.json'))
    commands = []
    for index, (purpose, schema, relative) in enumerate(command_files):
        record = inventory.json(relative)
        argv = record['argv']
        require(argv.count('-cp') == 1 and record['cwd'] == str(repo), 'Unexpected command classpath/cwd')
        cp = argv[argv.index('-cp') + 1]
        matches = [name for name, runtime in runtimes.items() if runtime['originalClasspath'] == cp]
        require(len(matches) == 1, 'Command must bind one frozen runtime')
        runtime_name = matches[0]
        require(source_argument(argv, schema) == runtimes[runtime_name]['sourceIdentity'], 'Command source differs')
        folder = relative.removesuffix('command.json')
        if schema == 'query-harness':
            raw_path = folder + 'samples.jsonl'
            metadata = json.loads(inventory.read(raw_path).splitlines()[0])
            main = argv[argv.index('-cp') + 2]
            require(main in {'org.eclipse.rdf4j.sail.lmdb.evaluation.RootQualifiedOptionalFanoutLauncher',
                             'org.eclipse.rdf4j.sail.lmdb.evaluation.RootQualifiedSharedSelectionLauncher'},
                    'Unexpected query entry point')
        else:
            raw_path = folder + 'probe.json'
            metadata = inventory.json(raw_path)
        require(metadata['source'] == runtimes[runtime_name]['sourceIdentity'], 'Raw metadata source differs')
        require(inventory.json(folder + 'process-result.json')['exitCode'] == 0, 'A recorded process failed')
        commands.append({'label': f'{index:02d}-' + relative.split('/')[-2], 'purpose': purpose,
                         'schema': schema, 'runtime': runtime_name, 'recordPath': 'rdf4j/' + relative,
                         'originalArgv': argv, 'originalCwd': record['cwd'],
                         'originalResultPath': 'rdf4j/' + raw_path, 'expectedMetadata': metadata,
                         'timeoutSeconds': 30 if schema == 'retry-probe' else 300})
    return {'artifacts': list(artifacts.values()), 'runtimes': runtimes, 'commands': commands,
            'primaryProtocolSha256': inventory.add(PHASE + '/protocol.json')['sha256'],
            'rawCompilerOutputs': raw_outputs}


def validate_extracted(repo, expected_manifest=None):
    manifest_path = path_under(repo, MANIFEST)
    data = manifest_path.read_bytes()
    require(expected_manifest is None or sha_bytes(data) == expected_manifest, 'Bundle manifest checksum differs')
    manifest = json.loads(data)
    require(manifest['format'] == 1 and manifest['archivePrefix'] == 'rdf4j'
            and manifest['selfContainedRuntime'] and not manifest['jdkIncluded'], 'Unexpected bundle manifest')
    inventory = Inventory(repo)
    for record in manifest['files']:
        actual = inventory.add(member_relative(record['path']), record['sha256'])
        require(actual == record, 'Extracted file metadata differs: ' + record['path'])
    artifacts = {entry['path']: entry for entry in manifest['runtimeArtifacts']}
    for artifact in artifacts.values():
        relative = member_relative(artifact['path'])
        if artifact['kind'] == 'tree':
            files = inventory.tree(relative)
            require(len(files) == artifact['files'] and tree_digest(files) == artifact['sha256'], 'Extracted tree differs')
        else:
            inventory.add(relative, artifact['sha256'])
    for runtime in manifest['runtimes'].values():
        require(runtime['originalClasspath'] == os.pathsep.join(entry['path'] for entry in runtime['originalManifest']),
                'Recorded classpath order differs')
        require(len(runtime['entries']) == len(runtime['originalManifest']), 'Runtime entry count differs')
        for path, original in zip(runtime['entries'], runtime['originalManifest']):
            require(path in artifacts, 'Runtime references an absent artifact')
            artifact = artifacts[path]
            require(artifact['originalAbsolutePath'] == original['path'] and artifact['kind'] == original['kind']
                    and artifact['sha256'] == original['sha256'] and artifact.get('files') == original.get('files'),
                    'Runtime artifact mapping differs')
    for command in manifest['commands']:
        raw = inventory.json(member_relative(command['recordPath']))
        require(raw['argv'] == command['originalArgv'] and raw['cwd'] == command['originalCwd'], 'Raw command differs')
        runtime = manifest['runtimes'][command['runtime']]
        argv = command['originalArgv']
        require(argv.count('-cp') == 1 and argv[argv.index('-cp') + 1] == runtime['originalClasspath']
                and source_argument(argv, command['schema']) == runtime['sourceIdentity'], 'Command/runtime differs')
    inventory.assert_stable()
    return manifest, sha_bytes(data)
